    local DISCORD_INVITE   = "https://discord.gg/YOUR_INVITE_HERE"
    local FEEDBACK_URL     = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
    local FEEDBACK_VERSION = "combowick-coldwar-0.1"
    local _request = request or (syn and syn.request) or http_request
    local function fbTrim(s) return (tostring(s or ""):gsub("^%s*(.-)%s*$", "%1")) end
    local FB_HWID = (function()
        local ok, id = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
        if ok and type(id) == "string" and id ~= "" then return id end
        return tostring(lp and lp.UserId or 0)
    end)()
    local FB_ERRMAP = {
        empty = "The message is empty.", no_links = "Links are not allowed.",
        too_long = "The message is too long (500 characters maximum).",
        rate_limited = "You have reached the limit of 3 messages. Please try again later.",
        busy = "The server is busy. Please try again.", banned = "You are not allowed to send feedback.",
        discord_error = "Sending failed. Please try again.", network = "Network error.",
        no_request = "Your executor cannot send requests.", bad_response = "The server returned an unexpected response.",
        unreachable = "Your executor cannot reach the server (TLS error). Please try a different executor.",
    }
    local function sendFeedback(ftype, msg)
        if not _request then return false, "no_request" end
        local ok, res = pcall(function()
            return _request({
                Url = FEEDBACK_URL, Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode({
                    type = ftype, message = msg, hwid = FB_HWID,
                    placeId = tostring(game.PlaceId), username = lp and lp.Name or "?",
                    version = FEEDBACK_VERSION,
                }),
            })
        end)
        if not ok or not res then return false, "network" end
        if type(res) == "string" then return false, "unreachable" end
        if type(res) ~= "table" then return false, "network" end
        local code = res.StatusCode or res.status_code or res.Status or res.status
        if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. tostring(code) end
        local body = res.Body or res.body
        if type(body) ~= "string" or body == "" then return false, "bad_response" end
        local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if not dok or type(data) ~= "table" then return false, "bad_response" end
        if data.success == true then return true end
        return false, tostring(data.error or "unknown")
    end

    local FG = FeedbackTab:AddLeftGroupbox("Suggestions / Help", "message-square")
    FG:AddDropdown("FeedbackType", { Text = "Type", Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
    FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "Message", Placeholder = "500 characters max, no links" })
    local fbStatus = FG:AddLabel("", true)
