local GUN_CACHE = {}
local function holdingGun()
    local ch = lp.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local tool = ch:FindFirstChildOfClass("Tool")
    if not tool then return false end
    local v = GUN_CACHE[tool.Name]
    if v == nil then
        local tools = game:GetService("ReplicatedStorage"):FindFirstChild("Tools")
        local src = tools and tools:FindFirstChild(tool.Name)
        v = src ~= nil and src:GetAttribute("ToolType") == "Weapon"
        GUN_CACHE[tool.Name] = v
    end
    return v
end
local STUDS_PER_M = 3.5714285714285716
local R6_PARTS = { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }

local function _buildCombat()
    local function installShot()
        if SES.hooks.shot3 then return true end
        if not G.shot then return false end
        local orig
        local function repl(...)
            local w = ST.shotWrap
            if w then
                local ok, a, b, c, d, e, f = pcall(w, ...)
                if ok and a ~= nil then return orig(a, b, c, d, e, f) end
            end
            return orig(...)
        end
        orig = hookLua(G.shot, repl, true)
        SES.hooks.shot3 = orig ~= nil
        SES.hooks.shot = SES.hooks.shot3
        return SES.hooks.shot3
    end
    local function installRecoil()
        if SES.hooks.recoil then return true end
        if not G.recoilKick then return false end
        local orig
        local function repl(...)
            if ST.noRecoil then return end
            return orig(...)
        end
        orig = hookLua(G.recoilKick, repl, true)
        SES.hooks.recoil = orig ~= nil
        return SES.hooks.recoil
    end
    local function installCycle()
        if SES.hooks.cycle then return true end
        if not G.cycle then return false end
        local orig
        local function repl(self, ...)
            if type(self) == "table" then
                pcall(function()
                    local base = rawget(self, "__cwBase")
                    if base == nil then
                        base = rawget(self, "shootDelay")
                        if type(base) == "number" then rawset(self, "__cwBase", base) end
                    end
                    if type(base) == "number" then
                        local m = ST.fireMult or 1
                        rawset(self, "shootDelay", m > 1 and base / m or base)
                    end
                end)
            end
            return orig(self, ...)
        end
        orig = hookLua(G.cycle, repl, false)
        SES.hooks.cycle = orig ~= nil
        return SES.hooks.cycle
    end

    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater = false

    local function prepRay()
        local cam = Workspace.CurrentCamera
        local list = { cam }
        if lp.Character then list[#list + 1] = lp.Character end
        local ig = Workspace:FindFirstChild("Ignore")
        if ig then list[#list + 1] = ig end
        rayParams.FilterDescendantsInstances = list
        local team = lp.Team and lp.Team.Name
        pcall(function() rayParams.CollisionGroup = team and ("Ray" .. team) or "Default" end)
    end

    local function isDowned(ch)
        local cv = ch:FindFirstChild("CharacterValues")
        local u = cv and cv:FindFirstChild("Unconscious")
        return u and u.Value == true
    end

    local function enemyPlayerOf(inst)
        local m = inst
        for _ = 1, 5 do
            if not m then return nil end
            local p = Players:GetPlayerFromCharacter(m)
            if p then return p, m end
            m = m.Parent
        end
        return nil
    end

    local function isValidEnemy(p, ch)
        if not p or p == lp then return false end
        local myTeam = lp.Team
        if not myTeam or not p.Team or p.Team == myTeam then return false end
        if p:GetAttribute("Invisible") then return false end
        if Toggles.cw_friends and Toggles.cw_friends.Value and FRIENDS[p.UserId] then return false end
        if not ch or not ch.Parent then return false end
        local hum = ch:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        if isDowned(ch) and not Toggles.cw_downed.Value then return false end
        return true, hum
    end

    local function visible(fromPos, part, ch)
        local dir = part.Position - fromPos
        local hit = Workspace:Raycast(fromPos, dir, rayParams)
        return (not hit) or hit.Instance:IsDescendantOf(ch)
    end

    local function aimPartOf(ch, center, cam)
        local mode = Opt.cw_part.Value
        if mode == "Head" or mode == "Torso" then return ch:FindFirstChild(mode) end
        local best, bd
        for _, n in ipairs(R6_PARTS) do
            local pt = ch:FindFirstChild(n)
            if pt then
                local sp, on = cam:WorldToViewportPoint(pt.Position)
                if on then
                    local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                    if not bd or d < bd then best, bd = pt, d end
                end
            end
        end
        return best or ch:FindFirstChild("Head")
    end

    local function pickTarget()
        local cam = Workspace.CurrentCamera
        if not cam or not lp.Team then return nil end
        prepRay()
        local camPos = cam.CFrame.Position
        local center = UserInputService:GetMouseLocation()
        local fov = Opt.cw_fov.Value
        local maxD = Opt.cw_maxdist.Value * STUDS_PER_M
        local cands = {}
        for _, p in ipairs(Players:GetPlayers()) do
            local ch = p.Character
            local ok, hum = isValidEnemy(p, ch)
            if ok then
                local part = aimPartOf(ch, center, cam)
                if part then
                    local d = (part.Position - camPos).Magnitude
                    if d <= maxD then
                        local sp, on = cam:WorldToViewportPoint(part.Position)
                        if on then
                            local sd = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                            if sd <= fov then
                                cands[#cands + 1] = { player = p, char = ch, part = part, sd = sd, d = d, hp = hum.Health }
                            end
                        end
                    end
                end
            end
        end
        if #cands == 0 then return nil end
        local prio = Opt.cw_prio.Value
        table.sort(cands, function(a, b)
            if prio == "Closest Distance" then return a.d < b.d end
            if prio == "Lowest Health" then return a.hp < b.hp end
            return a.sd < b.sd
        end)
        local needVis = Toggles.cw_wall.Value
        local function usable(c)
            if not needVis or visible(camPos, c.part, c.char) then return true end
            return false
        end
        if Toggles.cw_sticky.Value and T.current then
            for _, c in ipairs(cands) do
                if c.player == T.current.player and usable(c) then
                    return c
                end
            end
        end
        for i, c in ipairs(cands) do
            if i > 8 then break end
            if usable(c) then return c end
        end
        return nil
    end

    local function bulletOf(tool, mi, bi)
        local W = G.weapons
        if not W then return nil end
        local name = typeof(tool) == "Instance" and tool.Name or tool
        local muzzles = type(name) == "string" and W[name]
        local cfg = type(muzzles) == "table" and muzzles[mi or 1]
        local bs = type(cfg) == "table" and type(cfg.BulletSettings) == "table" and cfg.BulletSettings[bi or 1]
        if type(bs) ~= "table" then return nil end
        return bs.MuzzleVelocity or 0, bs.Drag or 1
    end

    local function solveDir(origin, targetPos, vel, V, K)
        local g = Workspace.Gravity
        local D = targetPos - origin
        if not V or V <= 0 then return D.Unit end
        local aim, t = D, 0
        for _ = 1, 6 do
            local s = aim.Magnitude
            if K > 1e-6 then
                local x = 1 - s * K / V
                if x <= 0 then return D.Unit end
                t = -math.log(x) / K
            else
                t = s / V
            end
            local tp = targetPos + (vel and vel * t or Vector3.zero)
            D = tp - origin
            aim = D + Vector3.new(0, 0.5 * g * t * t, 0)
        end
        return aim.Unit
    end

    local function targetVel(tg)
        if not Toggles.cw_predict.Value then return nil end
        local hrp = tg.char and tg.char:FindFirstChild("HumanoidRootPart")
        return hrp and hrp.AssemblyLinearVelocity or nil
    end

    local function silentDirs(tool, mi, bi, origin, dirs, opts)
        if not (Toggles.cw_silent and Toggles.cw_silent.Value) then return nil end
        if type(opts) == "table" and (opts.Networked == false or opts.Profile ~= nil) then return nil end
        if typeof(origin) ~= "Vector3" or type(dirs) ~= "table" or #dirs == 0 then return nil end
        local tg = T.current
        if not (tg and tg.part and tg.part.Parent) then return nil end
        local hc = Opt.cw_hitchance.Value
        if hc < 100 and math.random(1, 100) > hc then return nil end
        local V, K = bulletOf(tool, mi, bi)
        local dir = solveDir(origin, tg.part.Position, targetVel(tg), V, K or 1)
        if not dir or dir ~= dir then return nil end
        local out = table.create(#dirs)
        for i = 1, #dirs do out[i] = dir end
        return out
    end

    local function shotWrap(tool, mi, bi, origin, dirs, opts)
        local nd = silentDirs(tool, mi, bi, origin, dirs, opts)
        if not nd then return nil end
        return tool, mi, bi, origin, nd, opts
    end

    local SPREAD_ORIG = nil
    local function setNoSpread(on)
        local W = G.weapons
        if on then
            if SPREAD_ORIG or not W then return end
            SPREAD_ORIG = {}
            for _, muzzles in pairs(W) do
                if type(muzzles) == "table" then
                    for _, cfg in pairs(muzzles) do
                        if type(cfg) == "table" and type(cfg.BulletSettings) == "table" then
                            SPREAD_ORIG[#SPREAD_ORIG + 1] = { cfg, cfg.Spread }
                            cfg.Spread = 0
                            for _, bs in pairs(cfg.BulletSettings) do
                                if type(bs) == "table" then
                                    SPREAD_ORIG[#SPREAD_ORIG + 1] = { bs, bs.Spread }
                                    bs.Spread = 0
                                end
                            end
                        end
                    end
                end
            end
        elseif SPREAD_ORIG then
            for i = #SPREAD_ORIG, 1, -1 do
                local e = SPREAD_ORIG[i]
                e[1].Spread = e[2]
            end
            SPREAD_ORIG = nil
        end
    end
    onClean(function() setNoSpread(false) end)

    local TB = CombatTab:AddLeftGroupbox("Targeting", "crosshair")
    TB:AddDropdown("cw_part", { Text = "Aim Part", Values = { "Head", "Torso", "Closest" }, Default = "Head" })
    TB:AddDropdown("cw_prio", { Text = "Priority", Values = { "Closest To Crosshair", "Closest Distance", "Lowest Health" }, Default = "Closest To Crosshair" })
    TB:AddSlider("cw_fov", { Text = "FOV", Default = 150, Min = 20, Max = 800, Rounding = 0, Suffix = " px" })
    TB:AddSlider("cw_maxdist", { Text = "Max Distance", Default = 600, Min = 25, Max = 1500, Rounding = 0, Suffix = " m" })
    TB:AddToggle("cw_wall", { Text = "Visible Only", Default = true, Tooltip = "Off = also targets enemies behind thin cover" })
    TB:AddToggle("cw_downed", { Text = "Target Downed", Default = false })
    TB:AddToggle("cw_sticky", { Text = "Sticky Target", Default = true, Tooltip = "Stays on one enemy until lost" })
    TB:AddToggle("cw_friends", { Text = "Ignore Friends", Default = true })
    TB:AddToggle("cw_showfov", { Text = "Show FOV", Default = true }):AddColorPicker("cw_fovcolor", { Default = Color3.fromRGB(255, 255, 255), Title = "FOV Color" })
    local lblTarget = TB:AddLabel("Target: none")

    local SB = CombatTab:AddLeftGroupbox("Silent Aim", "zap")
    SB:AddToggle("cw_silent", { Text = "Silent Aim", Default = false, Tooltip = "Bullets go to the target",
        Callback = function(v)
            if v and not installShot() then notify("Silent Aim unavailable on this executor") end
        end })
    SB:AddSlider("cw_hitchance", { Text = "Hit Chance", Default = 100, Min = 1, Max = 100, Rounding = 0, Suffix = "%" })
    SB:AddToggle("cw_predict", { Text = "Lead Moving Targets", Default = true })

    local AB = CombatTab:AddRightGroupbox("Aimbot", "crosshair")
    AB:AddToggle("cw_aimbot", { Text = "Aimbot", Default = false, Tooltip = "Moves your aim onto the target",
        Callback = function(v)
            if v and not mousemoverel then notify("Aimbot needs mousemoverel") end
        end })
    local AimDep = AB:AddDependencyBox()
    AimDep:AddToggle("cw_aim_rmb", { Text = "Only While Aiming", Default = true, Tooltip = "Hold right click" })
    AimDep:AddSlider("cw_smooth", { Text = "Smoothness", Default = 4, Min = 1, Max = 20, Rounding = 1 })
    AimDep:SetupDependencies({ { Toggles.cw_aimbot, true } })

    local TrB = CombatTab:AddRightGroupbox("Trigger Bot", "zap")
    TrB:AddToggle("cw_trigger", { Text = "Trigger Bot", Default = false, Tooltip = "Shoots when on an enemy",
        Callback = function(v)
            if v and not (mouse1press and mouse1release) then notify("Trigger Bot needs mouse1press") end
        end })
    local TrDep = TrB:AddDependencyBox()
    TrDep:AddDropdown("cw_trig_when", { Text = "Fire When", Values = { "Crosshair On Enemy", "Silent Aim Has Target" }, Default = "Crosshair On Enemy" })
    TrDep:AddDropdown("cw_trig_mode", { Text = "Mode", Values = { "Hold", "Tap" }, Default = "Hold", Tooltip = "Tap for semi-auto guns" })
    TrDep:AddSlider("cw_trig_delay", { Text = "Reaction Delay", Default = 0.05, Min = 0, Max = 0.5, Rounding = 2, Suffix = " s" })
    TrDep:SetupDependencies({ { Toggles.cw_trigger, true } })

    local GB = CombatTab:AddRightGroupbox("Gun Mods", "swords")
    GB:AddToggle("cw_norecoil", { Text = "No Recoil", Default = false,
        Callback = function(v)
            ST.noRecoil = v
            if v and not installRecoil() then notify("No Recoil unavailable") end
        end })
    GB:AddToggle("cw_nospread", { Text = "No Spread", Default = false,
        Callback = function(v)
            if v and not G.weapons then notify("No Spread unavailable") return end
            setNoSpread(v)
        end })
    GB:AddToggle("cw_rapid", { Text = "Rapid Fire", Default = false, Tooltip = "Shoots faster",
        Callback = function(v)
            ST.fireMult = v and Opt.cw_rapid_mult and Opt.cw_rapid_mult.Value or 1
            if v and not installCycle() then notify("Rapid Fire unavailable") end
        end })
    local RapidDep = GB:AddDependencyBox()
    RapidDep:AddSlider("cw_rapid_mult", { Text = "Fire Rate", Default = 1.25, Min = 1, Max = 3, Rounding = 2, Suffix = "x",
        Callback = function(v) if Toggles.cw_rapid and Toggles.cw_rapid.Value then ST.fireMult = v end end })
    RapidDep:SetupDependencies({ { Toggles.cw_rapid, true } })

    GB:AddToggle("cw_fastreload", { Text = "Fast Reload", Default = false })
    local FrDep = GB:AddDependencyBox()
    FrDep:AddSlider("cw_reload_mult", { Text = "Reload Speed", Default = 2, Min = 1, Max = 5, Rounding = 1, Suffix = "x" })
    FrDep:SetupDependencies({ { Toggles.cw_fastreload, true } })

    local reloadIds = {}
    local function isReloadKey(k)
        return type(k) == "string" and (k:find("Reload") ~= nil or k:find("Insert") ~= nil or k == "BoltRelease"
            or k == "Discard" or k == "UnloadProjectile" or k == "EquipUnfold")
    end
    if G.weapons then
        for _, muzzles in pairs(G.weapons) do
            if type(muzzles) == "table" then
                for _, cfg in pairs(muzzles) do
                    if type(cfg) == "table" and type(cfg.Animations) == "table" then
                        for k, id in pairs(cfg.Animations) do
                            if isReloadKey(k) and type(id) == "string" then reloadIds[id] = true end
                        end
                    end
                end
            end
        end
    end
    local animConn
    local function bindAnimator(char)
        if animConn then animConn:Disconnect(); animConn = nil end
        local hum = char and char:WaitForChild("Humanoid", 10)
        local an = hum and hum:WaitForChild("Animator", 10)
        if not an or not RUNNING then return end
        animConn = an.AnimationPlayed:Connect(function(trk)
            if not (RUNNING and Toggles.cw_fastreload.Value) then return end
            local hit = isReloadKey(trk.Name)
            if not hit then
                pcall(function() hit = trk.Animation ~= nil and reloadIds[trk.Animation.AnimationId] == true end)
            end
            if hit then
                task.defer(function()
                    pcall(function() trk:AdjustSpeed(math.max(trk.Speed, 0.05) * Opt.cw_reload_mult.Value) end)
                end)
            end
        end)
    end
    task.spawn(bindAnimator, lp.Character)
    track(lp.CharacterAdded:Connect(function(c) task.spawn(bindAnimator, c) end))
    onClean(function() if animConn then animConn:Disconnect() end end)

    ST.silentDirs = nil
    ST.aimFn = nil
    ST.shotWrap = shotWrap
    onClean(function()
        ST.shotWrap = nil
        ST.noRecoil = false
        ST.fireMult = 1
    end)

    local fovGui = Instance.new("ScreenGui")
    fovGui.Name = "CW_Fov"
    fovGui.IgnoreGuiInset = true
    fovGui.ResetOnSpawn = false
    fovGui.DisplayOrder = 999
    local ring = Instance.new("Frame")
    ring.AnchorPoint = Vector2.new(0.5, 0.5)
    ring.BackgroundTransparency = 1
    ring.Parent = fovGui
    Instance.new("UICorner", ring).CornerRadius = UDim.new(1, 0)
    local stroke = Instance.new("UIStroke", ring)
    stroke.Thickness = 1.5
    stroke.Transparency = 0.25
    fovGui.Parent = guiParent()
    onClean(function() pcall(function() fovGui:Destroy() end) end)

    local trig = { pressed = false, onSince = nil, pressAt = 0, releaseAt = 0 }
    local function trigRelease()
        if trig.pressed and mouse1release then pcall(mouse1release) end
        trig.pressed = false
        trig.releaseAt = os.clock()
    end
    onClean(trigRelease)

    local function crosshairOnEnemy()
        local cam = Workspace.CurrentCamera
        if not cam then return false end
        prepRay()
        local m = UserInputService:GetMouseLocation()
        local ray = cam:ViewportPointToRay(m.X, m.Y)
        local hit = Workspace:Raycast(ray.Origin, ray.Direction * 5000, rayParams)
        if not hit then return false end
        local p, ch = enemyPlayerOf(hit.Instance)
        return p ~= nil and isValidEnemy(p, ch) == true
    end

    local lastLbl = ""
    track(RunService.RenderStepped:Connect(function()
        if not RUNNING then return end
        local silent  = Toggles.cw_silent.Value
        local aimbot  = Toggles.cw_aimbot.Value
        local trigger = Toggles.cw_trigger.Value
        local needTarget = silent or aimbot or (trigger and Opt.cw_trig_when.Value == "Silent Aim Has Target")

        local showFov = Toggles.cw_showfov.Value and (silent or aimbot)
        fovGui.Enabled = showFov
        if showFov then
            local c = UserInputService:GetMouseLocation()
            local d = Opt.cw_fov.Value * 2
            ring.Size = UDim2.fromOffset(d, d)
            ring.Position = UDim2.fromOffset(c.X, c.Y)
            stroke.Color = Opt.cw_fovcolor.Value
        end

        if needTarget then
            local ok, tg = pcall(pickTarget)
            T.current = ok and tg or nil
        else
            T.current = nil
        end
        local txt = "Target: none"
        if T.current then
            txt = ("Target: %s · %dm"):format(T.current.player.Name, math.floor(T.current.d / STUDS_PER_M))
        end
        if txt ~= lastLbl then lastLbl = txt; lblTarget:SetText(txt) end

        local menuOpen = Library.Toggled == true

        if aimbot and T.current and mousemoverel and not menuOpen
            and (not Toggles.cw_aim_rmb.Value or UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)) then
            local cam = Workspace.CurrentCamera
            local pos = T.current.part.Position
            local v = targetVel(T.current)
            if v then pos = pos + v * math.clamp(T.current.d / 2500, 0, 0.3) end
            local sp, on = cam:WorldToViewportPoint(pos)
            if on then
                local m = UserInputService:GetMouseLocation()
                local s = math.max(Opt.cw_smooth.Value, 1)
                pcall(mousemoverel, (sp.X - m.X) / s, (sp.Y - m.Y) / s)
            end
        end

        if trigger and mouse1press and not menuOpen and holdingGun() then
            local want
            if Opt.cw_trig_when.Value == "Silent Aim Has Target" then
                want = T.current ~= nil
            else
                local ok, r = pcall(crosshairOnEnemy)
                want = ok and r
            end
            local now = os.clock()
            if want then
                trig.onSince = trig.onSince or now
                if not trig.pressed then
                    if now - trig.onSince >= Opt.cw_trig_delay.Value and now - trig.releaseAt >= 0.06 then
                        pcall(mouse1press); trig.pressed = true; trig.pressAt = now
                    end
                elseif Opt.cw_trig_mode.Value == "Tap" and now - trig.pressAt >= 0.08 then
                    trigRelease()
                end
            else
                trig.onSince = nil
                if trig.pressed then trigRelease() end
            end
        elseif trig.pressed then
            trigRelease()
        end
    end))
end
section("Combat", _buildCombat)


local function _buildVisuals()
    local CollectionService = game:GetService("CollectionService")
    local hasDrawing = typeof(Drawing) == "table" and type(Drawing.new) == "function"
    local FONT = 2
    pcall(function() if Drawing.Fonts and Drawing.Fonts.Plex then FONT = Drawing.Fonts.Plex end end)
    local MAX_CHAMS = 25
    local BLACK = Color3.new(0, 0, 0)

    local EB = VisualsTab:AddLeftGroupbox("Player ESP", "eye")
    EB:AddToggle("esp_on", { Text = "ESP", Default = false, Tooltip = "Shows enemies through walls" })
    local EDep = EB:AddDependencyBox()
    EDep:AddToggle("esp_box", { Text = "Boxes", Default = true })
    EDep:AddToggle("esp_name", { Text = "Names", Default = true })
    EDep:AddToggle("esp_hp", { Text = "Health Bar", Default = true })
    EDep:AddToggle("esp_dist", { Text = "Distance", Default = true })
    EDep:AddToggle("esp_tracer", { Text = "Tracers", Default = false })
    EDep:AddToggle("esp_skel", { Text = "Skeleton", Default = false })
    EDep:AddToggle("esp_class", { Text = "Class", Default = true })
    EDep:AddToggle("esp_chams", { Text = "Chams", Default = true, Tooltip = "Glow through walls (nearest 25)" })
    EDep:AddToggle("esp_team", { Text = "Show Teammates", Default = false })
    EDep:SetupDependencies({ { Toggles.esp_on, true } })

    local CB = VisualsTab:AddRightGroupbox("ESP Settings", "settings")
    CB:AddSlider("esp_maxdist", { Text = "Max Distance", Default = 1000, Min = 50, Max = 2500, Rounding = 0, Suffix = " m" })
    CB:AddSlider("esp_textsize", { Text = "Text Size", Default = 13, Min = 9, Max = 20, Rounding = 0 })
    CB:AddLabel("Enemy"):AddColorPicker("esp_c_enemy", { Default = Color3.fromRGB(255, 70, 70), Title = "Enemy" })
    CB:AddToggle("esp_viscolor", { Text = "Visible Color", Default = true, Tooltip = "Different color when in sight" })
        :AddColorPicker("esp_c_vis", { Default = Color3.fromRGB(90, 255, 120), Title = "Visible" })
    CB:AddLabel("Teammate"):AddColorPicker("esp_c_team", { Default = Color3.fromRGB(80, 160, 255), Title = "Teammate" })
    if not hasDrawing then CB:AddLabel("Boxes/tracers off: no Drawing", true) end

    local folder = Instance.new("Folder")
    folder.Name = "CW_Esp"
    folder.Parent = guiParent()
    onClean(function() pcall(function() folder:Destroy() end) end)

    local ESP = {}
    local function newD(kind, props)
        local d = Drawing.new(kind)
        for k, v in pairs(props) do pcall(function() d[k] = v end) end
        return d
    end
    local function make(p)
        local o = { draw = {}, vis = false, visAt = 0 }
        if hasDrawing then
            o.boxO   = newD("Square", { Thickness = 3, Filled = false, Color = BLACK, Transparency = 0.5, Visible = false })
            o.box    = newD("Square", { Thickness = 1, Filled = false, Visible = false })
            o.hpBg   = newD("Line",   { Thickness = 4, Color = BLACK, Transparency = 0.6, Visible = false })
            o.hp     = newD("Line",   { Thickness = 2, Visible = false })
            o.tracer = newD("Line",   { Thickness = 1, Visible = false })
            o.name   = newD("Text",   { Center = true, Outline = true, Font = FONT, Visible = false })
            o.info   = newD("Text",   { Center = true, Outline = true, Font = FONT, Visible = false })
            o.draw = { o.boxO, o.box, o.hpBg, o.hp, o.tracer, o.name, o.info }
            o.skel = {}
            for i = 1, 9 do
                local l = newD("Line", { Thickness = 1.5, Visible = false })
                o.skel[i] = l
                o.draw[#o.draw + 1] = l
            end
        else
            local bb = Instance.new("BillboardGui")
            bb.AlwaysOnTop = true
            bb.Size = UDim2.fromOffset(200, 34)
            bb.StudsOffset = Vector3.new(0, 3, 0)
            bb.Enabled = false
            local tl = Instance.new("TextLabel")
            tl.BackgroundTransparency = 1
            tl.Size = UDim2.fromScale(1, 1)
            tl.Font = Enum.Font.GothamBold
            tl.TextStrokeTransparency = 0.3
            tl.Parent = bb
            bb.Parent = folder
            o.bb, o.bbText = bb, tl
        end
        local hl = Instance.new("Highlight")
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.FillTransparency = 0.65
        hl.OutlineTransparency = 0
        hl.Enabled = false
        hl.Parent = folder
        o.hl = hl
        ESP[p] = o
        return o
    end
    local function hideDraw(o)
        for _, d in ipairs(o.draw) do d.Visible = false end
        if o.bb then o.bb.Enabled = false end
    end
    local function hideAll(o)
        hideDraw(o)
        o.hl.Enabled = false
    end
    local function destroy(o)
        for _, d in ipairs(o.draw) do pcall(function() d:Remove() end) end
        if o.bb then pcall(function() o.bb:Destroy() end) end
        pcall(function() o.hl:Destroy() end)
    end
    track(Players.PlayerRemoving:Connect(function(p)
        local o = ESP[p]
        if o then destroy(o); ESP[p] = nil end
    end))
    onClean(function()
        for p, o in pairs(ESP) do destroy(o) end
        ESP = {}
    end)

    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local function checkVisible(o, ch, head, camPos, now)
        if now - o.visAt < 0.15 then return o.vis end
        o.visAt = now
        local list = { Workspace.CurrentCamera }
        if lp.Character then list[#list + 1] = lp.Character end
        local ig = Workspace:FindFirstChild("Ignore")
        if ig then list[#list + 1] = ig end
        rp.FilterDescendantsInstances = list
        local team = lp.Team and lp.Team.Name
        pcall(function() rp.CollisionGroup = team and ("Ray" .. team) or "Default" end)
        local hit = Workspace:Raycast(camPos, head.Position - camPos, rp)
        o.vis = (not hit) or hit.Instance:IsDescendantOf(ch)
        return o.vis
    end

    local function tagsOf(p, ch)
        local t = {}
        local cv = ch:FindFirstChild("CharacterValues")
        local u = cv and cv:FindFirstChild("Unconscious")
        if u and u.Value then t[#t + 1] = "DOWNED" end
        if CollectionService:HasTag(ch, "Disguised") then t[#t + 1] = "DISGUISED" end
        if p:GetAttribute("Invisible") then t[#t + 1] = "INVIS" end
        if STAFF[p.UserId] then t[#t + 1] = "STAFF" end
        if ch:GetAttribute("SpottedBy") then t[#t + 1] = "SPOTTED" end
        local cls = p:GetAttribute("ClassName")
        if Toggles.esp_class.Value and cls then t[#t + 1] = tostring(cls) end
        return t
    end

    local wasOn = false
    track(RunService.RenderStepped:Connect(function()
        if not RUNNING then return end
        if not Toggles.esp_on.Value then
            if wasOn then for _, o in pairs(ESP) do hideAll(o) end end
            wasOn = false
            return
        end
        wasOn = true
        local cam = Workspace.CurrentCamera
        if not cam then return end
        local camPos = cam.CFrame.Position
        local vp = cam.ViewportSize
        local myTeam = lp.Team
        local maxD = Opt.esp_maxdist.Value * STUDS_PER_M
        local tsize = Opt.esp_textsize.Value
        local cEnemy, cVis, cTeam = Opt.esp_c_enemy.Value, Opt.esp_c_vis.Value, Opt.esp_c_team.Value
        local now = os.clock()
        local chamList = {}

        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= lp then
                local o = ESP[p] or make(p)
                local ch = p.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                local root = ch and ch:FindFirstChild("HumanoidRootPart")
                local isTeam = myTeam ~= nil and p.Team == myTeam
                local show = ch and hum and root and hum.Health > 0 and p.Team ~= nil and (not isTeam or Toggles.esp_team.Value)
                local dist
                if show then
                    dist = (root.Position - camPos).Magnitude
                    if dist > maxD then show = false end
                end
                if not show then
                    hideAll(o)
                else
                    local head = ch:FindFirstChild("Head") or root
                    local color = cTeam
                    if not isTeam then
                        color = (Toggles.esp_viscolor.Value and checkVisible(o, ch, head, camPos, now)) and cVis or cEnemy
                    end
                    if STAFF[p.UserId] then color = Color3.fromRGB(200, 90, 255) end

                    if Toggles.esp_chams.Value then
                        chamList[#chamList + 1] = { o = o, ch = ch, d = dist, c = color }
                    end

                    local minX, minY, maxX, maxY, any = math.huge, math.huge, -math.huge, -math.huge, false
                    for _, n in ipairs(R6_PARTS) do
                        local pt = ch:FindFirstChild(n)
                        if pt then
                            local sp, on = cam:WorldToViewportPoint(pt.Position)
                            if sp.Z > 0 then
                                any = any or on
                                if sp.X < minX then minX = sp.X end
                                if sp.Y < minY then minY = sp.Y end
                                if sp.X > maxX then maxX = sp.X end
                                if sp.Y > maxY then maxY = sp.Y end
                            end
                        end
                    end

                    local meters = math.floor(dist / STUDS_PER_M)
                    local tags = tagsOf(p, ch)
                    local infoTxt = ""
                    if Toggles.esp_dist.Value then infoTxt = meters .. "m" end
                    if #tags > 0 then infoTxt = (infoTxt ~= "" and (infoTxt .. " · ") or "") .. table.concat(tags, " · ") end

                    if not any then
                        hideDraw(o)
                    elseif hasDrawing then
                        local h = math.max(maxY - minY, 6)
                        local pad = h * 0.12
                        local x, y = minX - pad, minY - pad
                        local w, hh = math.max(maxX - minX, h * 0.35) + pad * 2, h + pad * 2
                        if maxX - minX < h * 0.35 then x = (minX + maxX) / 2 - w / 2 end
                        local cx = x + w / 2

                        local showBox = Toggles.esp_box.Value
                        o.boxO.Visible, o.box.Visible = showBox, showBox
                        if showBox then
                            o.boxO.Position, o.boxO.Size = Vector2.new(x, y), Vector2.new(w, hh)
                            o.box.Position, o.box.Size = Vector2.new(x, y), Vector2.new(w, hh)
                            o.box.Color = color
                        end

                        local showHp = Toggles.esp_hp.Value
                        o.hpBg.Visible, o.hp.Visible = showHp, showHp
                        if showHp then
                            local frac = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                            local bx = x - 5
                            o.hpBg.From, o.hpBg.To = Vector2.new(bx, y + hh + 1), Vector2.new(bx, y - 1)
                            o.hp.From, o.hp.To = Vector2.new(bx, y + hh), Vector2.new(bx, y + hh - hh * frac)
                            o.hp.Color = Color3.fromRGB(255, 60, 60):Lerp(Color3.fromRGB(70, 255, 90), frac)
                        end

                        o.name.Visible = Toggles.esp_name.Value
                        if o.name.Visible then
                            o.name.Text = p.Name
                            o.name.Size = tsize
                            o.name.Color = color
                            o.name.Position = Vector2.new(cx, y - tsize - 2)
                        end

                        o.info.Visible = infoTxt ~= ""
                        if o.info.Visible then
                            o.info.Text = infoTxt
                            o.info.Size = tsize - 1
                            o.info.Color = Color3.fromRGB(230, 230, 230)
                            o.info.Position = Vector2.new(cx, y + hh + 2)
                        end

                        o.tracer.Visible = Toggles.esp_tracer.Value
                        if o.tracer.Visible then
                            o.tracer.From = Vector2.new(vp.X / 2, vp.Y)
                            o.tracer.To = Vector2.new(cx, y + hh)
                            o.tracer.Color = color
                        end

                        local showSk = Toggles.esp_skel.Value
                        if showSk then
                            local torso = ch:FindFirstChild("Torso")
                            local function sp(part, off)
                                if not part then return nil end
                                local v, on = cam:WorldToViewportPoint((part.CFrame * CFrame.new(off)).Position)
                                if v.Z <= 0 then return nil end
                                return Vector2.new(v.X, v.Y)
                            end
                            local la, ra = ch:FindFirstChild("Left Arm"), ch:FindFirstChild("Right Arm")
                            local ll, rl = ch:FindFirstChild("Left Leg"), ch:FindFirstChild("Right Leg")
                            local neck, pelvis = sp(torso, Vector3.new(0, 1, 0)), sp(torso, Vector3.new(0, -1, 0))
                            local segs = {
                                { sp(head, Vector3.zero), neck },
                                { neck, pelvis },
                                { neck, sp(la, Vector3.new(0, 0.8, 0)) },
                                { sp(la, Vector3.new(0, 0.8, 0)), sp(la, Vector3.new(0, -1, 0)) },
                                { neck, sp(ra, Vector3.new(0, 0.8, 0)) },
                                { sp(ra, Vector3.new(0, 0.8, 0)), sp(ra, Vector3.new(0, -1, 0)) },
                                { pelvis, sp(ll, Vector3.new(0, -1, 0)) },
                                { pelvis, sp(rl, Vector3.new(0, -1, 0)) },
                            }
                            for i = 1, 9 do
                                local l, sg = o.skel[i], segs[i]
                                if sg and sg[1] and sg[2] then
                                    l.From, l.To, l.Color, l.Visible = sg[1], sg[2], color, true
                                else
                                    l.Visible = false
                                end
                            end
                        else
                            for i = 1, 9 do o.skel[i].Visible = false end
                        end
                    else
                        o.bb.Adornee = head
                        o.bb.Enabled = Toggles.esp_name.Value or infoTxt ~= ""
                        local parts = {}
                        if Toggles.esp_name.Value then parts[#parts + 1] = p.Name end
                        if infoTxt ~= "" then parts[#parts + 1] = infoTxt end
                        o.bbText.Text = table.concat(parts, "\n")
                        o.bbText.TextColor3 = color
                        o.bbText.TextSize = tsize
                    end
                end
            end
        end

        table.sort(chamList, function(a, b) return a.d < b.d end)
        local want = {}
        for i, e in ipairs(chamList) do
            if i > MAX_CHAMS then break end
            want[e.o] = e
        end
        for _, o in pairs(ESP) do
            local e = want[o]
            if e then
                local hl = o.hl
                if hl.Adornee ~= e.ch then hl.Adornee = e.ch end
                if hl.FillColor ~= e.c then hl.FillColor = e.c; hl.OutlineColor = e.c end
                if not hl.Enabled then hl.Enabled = true end
            elseif o.hl.Enabled then
                o.hl.Enabled = false
            end
        end
    end))
end
section("Visuals", _buildVisuals)

local function _buildWorld()
    local Lighting = game:GetService("Lighting")
    local WB = VisualsTab:AddRightGroupbox("World", "eye")
    WB:AddToggle("w_bright", { Text = "Fullbright", Default = false })
    WB:AddToggle("w_nofog", { Text = "No Fog", Default = false })
    WB:AddToggle("w_fov", { Text = "Custom FOV", Default = false })
    local FovDep = WB:AddDependencyBox()
    FovDep:AddSlider("w_fov_val", { Text = "Field Of View", Default = 90, Min = 70, Max = 120, Rounding = 0 })
    FovDep:SetupDependencies({ { Toggles.w_fov, true } })

    local origL = {}
    local function saveL(obj, props)
        for _, k in ipairs(props) do
            local key = obj:GetFullName() .. "." .. k
            if origL[key] == nil then origL[key] = { obj, k, obj[k] } end
        end
    end
    local function restoreL(prefix)
        for key, e in pairs(origL) do
            if key:find(prefix, 1, true) then pcall(function() e[1][e[2]] = e[3] end); origL[key] = nil end
        end
    end
    local busy = false
    local function apply()
        if busy or not RUNNING then return end
        busy = true
        if Toggles.w_bright.Value then
            saveL(Lighting, { "Brightness", "ClockTime", "OutdoorAmbient", "Ambient", "ExposureCompensation" })
            Lighting.Brightness = 2
            Lighting.ClockTime = 13
            Lighting.OutdoorAmbient = Color3.fromRGB(170, 170, 170)
            Lighting.Ambient = Color3.fromRGB(140, 140, 140)
            Lighting.ExposureCompensation = 0.3
        end
        if Toggles.w_nofog.Value then
            local atm = Lighting:FindFirstChildOfClass("Atmosphere")
            if atm then
                saveL(atm, { "Density", "Haze" })
                atm.Density = 0
                atm.Haze = 0
            end
            saveL(Lighting, { "FogEnd" })
            Lighting.FogEnd = 1e6
        end
        busy = false
    end
    Toggles.w_bright:OnChanged(function(v)
        if v then apply() else restoreL("Lighting.Brightness"); restoreL("Lighting.ClockTime"); restoreL("Lighting.OutdoorAmbient"); restoreL("Lighting.Ambient"); restoreL("Lighting.ExposureCompensation") end
    end)
    Toggles.w_nofog:OnChanged(function(v)
        if v then apply() else restoreL("Atmosphere"); restoreL("Lighting.FogEnd") end
    end)
    track(Lighting.Changed:Connect(function() task.defer(apply) end))
    local atm = Lighting:FindFirstChildOfClass("Atmosphere")
    if atm then track(atm.Changed:Connect(function() task.defer(apply) end)) end
    onClean(function() restoreL("") end)

    local fovBase, fovWritten
    RunService:BindToRenderStep("CW_Fov", Enum.RenderPriority.Camera.Value + 5, function()
        local cam = Workspace.CurrentCamera
        if not cam then return end
        local cur = cam.FieldOfView
        if not (RUNNING and Toggles.w_fov.Value) then
            if fovWritten and fovBase and math.abs(cur - fovWritten) < 0.01 then cam.FieldOfView = fovBase end
            fovBase, fovWritten = nil, nil
            return
        end
        if not fovWritten or math.abs(cur - fovWritten) > 0.01 then fovBase = cur end
        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then fovWritten = nil return end
        fovWritten = math.clamp(fovBase * Opt.w_fov_val.Value / 70, 1, 120)
        cam.FieldOfView = fovWritten
    end)
    onClean(function() pcall(function() RunService:UnbindFromRenderStep("CW_Fov") end) end)
end
section("World", _buildWorld)

local function _buildWorldEsp()
    local RS = game:GetService("ReplicatedStorage")
    local hasDrawing = typeof(Drawing) == "table" and type(Drawing.new) == "function"
    local OB = VisualsTab:AddLeftGroupbox("World ESP", "eye")
    OB:AddToggle("ve_on", { Text = "Vehicle ESP", Default = false })
    local VeDep = OB:AddDependencyBox()
    VeDep:AddToggle("ve_friendly", { Text = "Show Friendly Vehicles", Default = false })
    VeDep:AddToggle("ve_wrecked", { Text = "Show Wrecked", Default = false })
    VeDep:SetupDependencies({ { Toggles.ve_on, true } })
    OB:AddToggle("ob_on", { Text = "Objective ESP", Default = false })
    OB:AddToggle("sc_on", { Text = "Sector ESP", Default = false, Tooltip = "Frontline mode" })
    OB:AddLabel("Frontline: use Sector ESP", true)
    if not hasDrawing then OB:AddLabel("Needs Drawing support", true) return end

    local FONT = 2
    pcall(function() if Drawing.Fonts and Drawing.Fonts.Plex then FONT = Drawing.Fonts.Plex end end)
    local pool, used = {}, {}
    local function text(key)
        local d = pool[key]
        if not d then
            d = Drawing.new("Text")
            d.Center, d.Outline, d.Font, d.Size = true, true, FONT, 13
            pool[key] = d
        end
        used[key] = true
        return d
    end
    onClean(function() for _, d in pairs(pool) do pcall(function() d:Remove() end) end pool = {} end)

    local RED, BLUE, WHITE, YELLOW = Color3.fromRGB(255, 80, 80), Color3.fromRGB(90, 160, 255), Color3.fromRGB(235, 235, 235), Color3.fromRGB(255, 210, 60)
    local function teamColor(name)
        local my = lp.Team and lp.Team.Name
        if not name or name == "Neutral" then return WHITE end
        return name == my and BLUE or RED
    end
    local function place(key, pos, str, color, cam)
        local v, on = cam:WorldToViewportPoint(pos)
        if not on or v.Z <= 0 then return end
        local d = text(key)
        d.Position = Vector2.new(v.X, v.Y)
        d.Text = str
        d.Color = color
        d.Visible = true
    end

    local SB
    local sectorCache, sectorAt = {}, 0
    local function refreshSectors(camPos)
        if not SB then
            local ok, t = pcall(require, RS.Client.MatchHud.SectorBoard)
            SB = ok and type(t) == "table" and t or false
        end
        if not SB then return end
        local okG, grid = gcall(SB.GetGrid)
        if not okG or type(grid) ~= "table" or not grid.Columns then sectorCache = {} return end
        local list = {}
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = { Workspace:FindFirstChild("Characters"), Workspace:FindFirstChild("Ignore"), Workspace:FindFirstChild("Vehicles") }
        for col = 1, grid.Columns do
            for row = 1, grid.Rows do
                local i = (col - 1) * grid.Rows + row
                local x = grid.MinX + (col - 0.5) * grid.SectorSize
                local z = grid.MinZ + (row - 0.5) * grid.SectorSize
                if (Vector3.new(x, camPos.Y, z) - camPos).Magnitude < 2200 then
                    local ok, owner, contested, capturing = gcall(SB.GetState, i)
                    if ok then
                        local hit = Workspace:Raycast(Vector3.new(x, 2000, z), Vector3.new(0, -4000, 0), rp)
                        list[#list + 1] = { pos = Vector3.new(x, (hit and hit.Position.Y or camPos.Y) + 8, z), owner = owner, contested = contested, capturing = capturing }
                    end
                end
            end
        end
        sectorCache = list
    end

    track(RunService.RenderStepped:Connect(function()
        if not RUNNING then return end
        used = {}
        local cam = Workspace.CurrentCamera
        if cam then
            local camPos = cam.CFrame.Position
            local my = lp.Team and lp.Team.Name

            if Toggles.ve_on.Value then
                local folder = Workspace:FindFirstChild("Vehicles")
                if folder then
                    for _, v in ipairs(folder:GetChildren()) do
                        local root = v.PrimaryPart or v:FindFirstChild("RootPart")
                        local wrecked = v:GetAttribute("Wrecked") == true
                        local side = v:GetAttribute("CrewTeam") or v:GetAttribute("Team")
                        local enemy = side ~= my
                        if root and (enemy or Toggles.ve_friendly.Value) and (not wrecked or Toggles.ve_wrecked.Value) then
                            local dist = math.floor((root.Position - camPos).Magnitude / STUDS_PER_M)
                            local driver
                            local seats = v:FindFirstChild("Seats")
                            local ds = seats and seats:FindFirstChild("DriverSeat")
                            local occ = ds and ds:FindFirstChild("Occupant")
                            if occ and occ.Value then
                                local p = Players:GetPlayerFromCharacter(occ.Value)
                                driver = p and p.Name
                            end
                            local crew = 0
                            if seats then
                                for _, s in ipairs(seats:GetChildren()) do
                                    local o = s:FindFirstChild("Occupant")
                                    if o and o.Value then crew = crew + 1 end
                                end
                            end
                            local str = ("%s · %dm"):format(v:GetAttribute("VehicleName") or v.Name, dist)
                            if crew > 0 then str = str .. (" · %d crew"):format(crew) end
                            if driver then str = str .. "\n" .. driver end
                            if wrecked then str = str .. "\nWRECKED" end
                            place("v" .. tostring(v:GetAttribute("VehicleNetId") or v.Name), root.Position + Vector3.new(0, 6, 0), str, wrecked and WHITE or teamColor(side), cam)
                        end
                    end
                end
            end

            if Toggles.ob_on.Value then
                local match = Workspace:FindFirstChild("Match")
                local objs = match and match:FindFirstChild("Objectives")
                if objs then
                    for _, ov in ipairs(objs:GetChildren()) do
                        local part = ov:IsA("ObjectValue") and ov.Value
                        if part and part:IsA("BasePart") then
                            local td = part:FindFirstChild("TriggerData")
                            local ct = td and td:FindFirstChild("CapturedTeam")
                            local cp = td and td:FindFirstChild("CaptureProgress")
                            local owner = ct and ct.Value and ct.Value.Name or "Neutral"
                            local prog = cp and cp.Value or 0
                            local order = ov:GetAttribute("Order") or 0
                            local letter = (order >= 1 and order <= 26) and string.char(64 + order) or "?"
                            local dist = math.floor((part.Position - camPos).Magnitude / STUDS_PER_M)
                            local str = ("[%s] %s · %dm"):format(letter, owner, dist)
                            local capping = (prog > 0 and prog < 100 and owner ~= "NATO") or (prog < 0 and prog > -100 and owner ~= "PACT")
                            if capping then str = str .. ("\n%s %d%%"):format(prog > 0 and "NATO" or "PACT", math.floor(math.abs(prog))) end
                            place("o" .. ov.Name .. order, part.Position + Vector3.new(0, part.Size.Y / 2 + 6, 0), str, capping and YELLOW or teamColor(owner), cam)
                        end
                    end
                end
            end

            if Toggles.sc_on.Value then
                if os.clock() - sectorAt > 1 then sectorAt = os.clock(); pcall(refreshSectors, camPos) end
                for i, s in ipairs(sectorCache) do
                    local str = s.contested and ("CONTESTED · " .. tostring(s.capturing)) or tostring(s.owner)
                    str = str .. (" · %dm"):format(math.floor((s.pos - camPos).Magnitude / STUDS_PER_M))
                    place("s" .. i, s.pos, str, s.contested and YELLOW or teamColor(s.owner), cam)
                end
            end
        end
        for k, d in pairs(pool) do
            if not used[k] then
                if d.Visible then d.Visible = false end
                if k:sub(1, 1) == "v" and not Toggles.ve_on.Value then pcall(function() d:Remove() end); pool[k] = nil end
            end
        end
    end))
end
section("World ESP", _buildWorldEsp)

local function _buildMilsim()
    local RS = game:GetService("ReplicatedStorage")
    local Remotes = RS:WaitForChild("Remotes")
    local rBino, rRadio, rRevive, rMedic = Remotes:FindFirstChild("Binoculars"), Remotes:FindFirstChild("Radio"), Remotes:FindFirstChild("BeingRevived"), Remotes:FindFirstChild("MedicBag")

    local function myChar() return lp.Character end
    local function myHead() local c = myChar() return c and c:FindFirstChild("Head") end
    local function cv(name)
        local c = myChar()
        local f = c and c:FindFirstChild("CharacterValues")
        return f and f:FindFirstChild(name)
    end
    local function classType() local v = cv("ClassType") return v and v.Value or lp:GetAttribute("ClassType") end
    local function isMedic() return tostring(lp:GetAttribute("ClassName") or ""):find("Medic") ~= nil end
    local function hasTool(name)
        local c, bp = myChar(), lp:FindFirstChildOfClass("Backpack")
        for _, root in ipairs({ c, bp }) do
            if root then
                for _, t in ipairs(root:GetChildren()) do
                    if t:IsA("Tool") and t.Name:find(name) then return t end
                end
            end
        end
    end
    local function downed(ch)
        local f = ch and ch:FindFirstChild("CharacterValues")
        local u = f and f:FindFirstChild("Unconscious")
        return u and u.Value == true
    end
    local function alive(ch)
        local h = ch and ch:FindFirstChildOfClass("Humanoid")
        return h and h.Health > 0
    end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local function losFromHead(pos, ch)
        local head = myHead()
        if not head then return false end
        local list = { Workspace.CurrentCamera }
        if myChar() then list[#list + 1] = myChar() end
        if Workspace:FindFirstChild("Ignore") then list[#list + 1] = Workspace.Ignore end
        rp.FilterDescendantsInstances = list
        local hit = Workspace:Raycast(head.Position, pos - head.Position, rp)
        return (not hit) or (ch and hit.Instance:IsDescendantOf(ch)) or (hit.Position - pos).Magnitude < 8
    end
    local function enemies()
        local out = {}
        local my = lp.Team
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= lp and my and p.Team and p.Team ~= my then
                local ch = p.Character
                local root = ch and ch:FindFirstChild("HumanoidRootPart")
                if root and alive(ch) then out[#out + 1] = { p = p, ch = ch, pos = root.Position } end
            end
        end
        return out
    end

    local KB = MilsimTab:AddLeftGroupbox("Fire Support", "zap")
    KB:AddDropdown("ms_strike", { Text = "Strike", Values = { "ArtilleryHE", "Airstrike" }, Default = "ArtilleryHE" })
    KB:AddSlider("ms_strike_range", { Text = "Max Range", Default = 600, Min = 100, Max = 1500, Rounding = 0, Suffix = " m" })
    local lblStrike = KB:AddLabel("Strike: ready")
    local cooldownUntil = 0
    if rRadio then track(rRadio.OnClientEvent:Connect(function(name, secs)
        if name == Opt.ms_strike.Value and type(secs) == "number" then cooldownUntil = os.clock() + secs end
    end)) end
    local function bestCluster()
        local head = myHead()
        if not head then return nil end
        local list = enemies()
        local maxD = Opt.ms_strike_range.Value * STUDS_PER_M
        local best, bestN
        for _, e in ipairs(list) do
            if (e.pos - head.Position).Magnitude <= maxD and losFromHead(e.pos, e.ch) then
                local n = 0
                for _, o in ipairs(list) do if (o.pos - e.pos).Magnitude < 30 then n = n + 1 end end
                if not bestN or n > bestN then best, bestN = e, n end
            end
        end
        return best, bestN
    end
    local striking = false
    local function strike(target)
        if striking then return false, "busy" end
        if classType() ~= "Command" then return false, "need Command class" end
        if not (rBino and rRadio) then return false, "remotes missing" end
        if os.clock() < cooldownUntil then return false, ("cooldown %ds"):format(math.ceil(cooldownUntil - os.clock())) end
        local head = myHead()
        if not (head and target) then return false, "no target" end
        striking = true
        local dp = cv("DesignatedPosition")
        local before = dp and dp.Value
        rBino:FireServer("Designate", (target.pos - head.Position).Unit)
        local t0 = os.clock()
        while dp and dp.Value == before and os.clock() - t0 < 2.5 do task.wait(0.1) end
        rRadio:FireServer("Callout", Opt.ms_strike.Value)
        striking = false
        return true
    end
    KB:AddButton({ Text = "Strike Best Target", Func = function()
        task.spawn(function()
            local t, n = bestCluster()
            local ok, why = strike(t)
            notify(ok and (("Strike on %s (%d nearby)"):format(t.p.Name, n)) or ("Strike: " .. tostring(why)))
        end)
    end })
    KB:AddToggle("ms_arty", { Text = "Auto Strike", Default = false, Tooltip = "Calls strikes on enemy groups" })
    KB:AddSlider("ms_arty_min", { Text = "Min Enemies", Default = 2, Min = 1, Max = 8, Rounding = 0 })

    local SpB = MilsimTab:AddLeftGroupbox("Recon", "eye")
    SpB:AddToggle("ms_autospot", { Text = "Auto Spot", Default = false, Tooltip = "Marks enemies for your team" })
    local lblSpot = SpB:AddLabel("Spot: off")
    local spotUntil = 0
    if rBino then track(rBino.OnClientEvent:Connect(function(secs)
        if type(secs) == "number" then spotUntil = os.clock() + secs end
    end)) end

    local MdB = MilsimTab:AddRightGroupbox("Medic", "life-buoy")
    MdB:AddToggle("ms_autorevive", { Text = "Auto Revive", Default = false, Tooltip = "Revives downed teammates near you" })
    MdB:AddToggle("ms_autoheal", { Text = "Auto Heal", Default = false, Tooltip = "Medic bag on you and nearby teammates" })
    local lblMed = MdB:AddLabel("Medic: idle")

    local reviving = false
    local function tryRevive()
        if reviving or not rRevive then return end
        local me = myChar()
        local root = me and me:FindFirstChild("HumanoidRootPart")
        if not root or not alive(me) or downed(me) then return end
        local my = lp.Team
        for _, p in ipairs(Players:GetPlayers()) do
            local ch = p.Character
            local tr = ch and ch:FindFirstChild("HumanoidRootPart")
            if p ~= lp and p.Team == my and tr and alive(ch) and downed(ch) and (tr.Position - root.Position).Magnitude <= 6.5 then
                reviving = true
                local dur = isMedic() and 3 or 10
                lblMed:SetText("Reviving " .. p.Name)
                rRevive:FireServer("begin", p)
                local t0, ok = os.clock(), true
                while os.clock() - t0 < dur + 0.25 do
                    task.wait(0.1)
                    local r2 = myChar() and myChar():FindFirstChild("HumanoidRootPart")
                    if not (RUNNING and Toggles.ms_autorevive.Value and r2 and tr.Parent and downed(ch)) or (tr.Position - r2.Position).Magnitude > 7 then ok = false break end
                end
                if ok then rRevive:FireServer("complete", p) else rRevive:FireServer("cancel", p, true) end
                lblMed:SetText(ok and ("Revived " .. p.Name) or "Medic: idle")
                reviving = false
                return
            end
        end
    end

    local function hurt(ch)
        local h = ch and ch:FindFirstChildOfClass("Humanoid")
        if h and h.Health < h.MaxHealth - 0.5 then return true end
        for _, n in ipairs(R6_PARTS) do
            local part = ch and ch:FindFirstChild(n)
            local hv = part and part:FindFirstChild("Health")
            local mx = hv and hv:GetAttribute("MaxHealth")
            if hv and mx and hv.Value < mx - 0.5 then return true end
        end
        return false
    end
    local healing = nil
    local function stopHeal()
        if healing and rMedic then pcall(function() rMedic:FireServer(healing, false) end) end
        healing = nil
    end
    local function tryHeal()
        if not rMedic or not hasTool("Medic") then stopHeal() return end
        local me = myChar()
        local root = me and me:FindFirstChild("HumanoidRootPart")
        if not root or not alive(me) or downed(me) then stopHeal() return end
        local want
        if hurt(me) then want = me end
        if not want then
            for _, p in ipairs(Players:GetPlayers()) do
                local ch = p.Character
                local tr = ch and ch:FindFirstChild("HumanoidRootPart")
                if p ~= lp and p.Team == lp.Team and tr and alive(ch) and not downed(ch) and hurt(ch) and (tr.Position - root.Position).Magnitude <= 6.5 then
                    want = ch break
                end
            end
        end
        if want ~= healing then
            stopHeal()
            if want then
                rMedic:FireServer(want, true)
                healing = want
                lblMed:SetText("Healing " .. (want == me and "self" or want.Name))
            end
        end
    end
    onClean(stopHeal)

    task.spawn(function()
        while RUNNING do
            task.wait(0.4)
            pcall(function()
                if Toggles.ms_autorevive.Value then task.spawn(tryRevive) end
                if Toggles.ms_autoheal.Value then tryHeal() elseif healing then stopHeal() end

                local bino = hasTool("Binocular")
                lblSpot:SetText(not Toggles.ms_autospot.Value and "Spot: off" or (bino and (os.clock() < spotUntil and "Spot: cooling down" or "Spot: watching") or "Spot: need binoculars"))
                if Toggles.ms_autospot.Value and bino and rBino and os.clock() >= spotUntil and not striking then
                    local head = myHead()
                    if head then
                        for _, e in ipairs(enemies()) do
                            local ch = e.ch
                            if not ch:GetAttribute("SpottedBy") and (e.pos - head.Position).Magnitude < 1500 and losFromHead(e.pos, ch) then
                                rBino:FireServer("Spotting", (e.pos - head.Position).Unit)
                                spotUntil = os.clock() + 2
                                break
                            end
                        end
                    end
                end

                local left = cooldownUntil - os.clock()
                lblStrike:SetText(classType() ~= "Command" and "Strike: need Command class" or (left > 0 and ("Strike: %ds"):format(math.ceil(left)) or "Strike: ready"))
                if Toggles.ms_arty.Value and left <= 0 and not striking then
                    local t, n = bestCluster()
                    if t and n >= Opt.ms_arty_min.Value then task.spawn(strike, t) end
                end
            end)
        end
    end)

    local VB = MilsimTab:AddRightGroupbox("Vehicle", "fast-forward")
    VB:AddToggle("vh_on", { Text = "Vehicle Mods", Default = false, Tooltip = "Applies while you drive" })
    local VhDep = VB:AddDependencyBox()
    VhDep:AddSlider("vh_speed", { Text = "Top Speed", Default = 1.5, Min = 1, Max = 4, Rounding = 2, Suffix = "x" })
    VhDep:AddSlider("vh_accel", { Text = "Acceleration", Default = 1.5, Min = 1, Max = 4, Rounding = 2, Suffix = "x" })
    VhDep:AddSlider("vh_grip", { Text = "Grip", Default = 1.3, Min = 1, Max = 3, Rounding = 2, Suffix = "x" })
    VhDep:SetupDependencies({ { Toggles.vh_on, true } })
    local lblVeh = VB:AddLabel("Vehicle: not driving")

    local DC, dcTried = nil, false
    local function driveState()
        if not dcTried then
            dcTried = true
            pcall(function() DC = require(RS.Shared.Vehicle.DriverController) end)
        end
        if not (DC and type(DC.GetVehicle) == "function" and getupvalues) then return nil end
        local ok, ups = pcall(getupvalues, DC.GetVehicle)
        if not ok then return nil end
        for _, u in pairs(ups) do
            if type(u) == "table" and type(rawget(u, "drive")) == "table" then return u end
        end
    end
    local touched = setmetatable({}, { __mode = "k" })
    local function scale(t, key, mult)
        if type(t) ~= "table" or type(rawget(t, key)) ~= "number" then return end
        local b = touched[t] or {}
        touched[t] = b
        if b[key] == nil then b[key] = t[key] end
        t[key] = b[key] * mult
    end
    local function applyVehicle(on)
        local st = driveState()
        local drive = st and st.drive
        if type(drive) ~= "table" then
            lblVeh:SetText(DC and "Vehicle: not driving" or "Vehicle: unavailable")
            return
        end
        lblVeh:SetText(on and "Vehicle: boosted" or "Vehicle: stock")
        local sp = on and Opt.vh_speed.Value or 1
        local ac = on and Opt.vh_accel.Value or 1
        local gr = on and Opt.vh_grip.Value or 1
        scale(drive, "dragK", 1 / (sp * sp))
        if type(drive.engine) == "table" then
            scale(drive.engine, "finalDrive", 1 / sp)
            scale(drive.engine, "torqueScale", ac * sp)
        end
        if type(drive.wheels) == "table" then
            for _, w in pairs(drive.wheels) do
                for _, k in ipairs({ "Grip", "PeakGrip", "SlideGrip" }) do scale(w, k, gr) end
            end
        end
        for _, k in ipairs({ "mu", "latMu", "latGrip" }) do scale(drive, k, gr) end
    end
    local vehWasOn = false
    task.spawn(function()
        while RUNNING do
            task.wait(0.5)
            local on = Toggles.vh_on.Value
            if on or vehWasOn then pcall(applyVehicle, on) end
            vehWasOn = on
        end
    end)
    onClean(function() if dcTried then pcall(applyVehicle, false) end end)
end
section("Milsim", _buildMilsim)

local function _buildMovement()
    local MB = MoveTab:AddLeftGroupbox("Movement", "fast-forward")
    MB:AddToggle("mv_speed", { Text = "Speed", Default = false })
    local SpDep = MB:AddDependencyBox()
    SpDep:AddSlider("mv_speed_mult", { Text = "Speed Boost", Default = 1.4, Min = 1, Max = 3, Rounding = 2, Suffix = "x" })
    SpDep:SetupDependencies({ { Toggles.mv_speed, true } })

    MB:AddToggle("mv_fly", { Text = "Fly", Default = false, Tooltip = "Space up · Ctrl down" })
        :AddKeyPicker("mv_fly_key", { Default = "Z", Mode = "Toggle", Text = "Fly", SyncToggleState = true })
    local FlyDep = MB:AddDependencyBox()
    FlyDep:AddSlider("mv_fly_speed", { Text = "Fly Speed", Default = 45, Min = 10, Max = 120, Rounding = 0 })
    FlyDep:SetupDependencies({ { Toggles.mv_fly, true } })

    local XB = MoveTab:AddRightGroupbox("Extras", "zap")
    XB:AddButton({ Text = "Unlock Freecam", Tooltip = "Shift + P toggles it", Func = function()
        local pa = lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("PrivateAttributes")
        if pa then pa:SetAttribute("FreecamAllowed", true); notify("Freecam unlocked · Shift + P") else notify("Freecam not available") end
    end })

    local speedTables, speedResolved = {}, false
    local function resolveSpeed()
        if speedResolved then return next(speedTables) ~= nil end
        speedResolved = true
        pcall(function()
            local t = require(game:GetService("ReplicatedStorage").Client.Character.stance.StanceState)
            if type(t) == "table" and type(t.WALK_SPEED) == "table" then speedTables[t.WALK_SPEED] = true end
        end)
        if next(speedTables) == nil and getgc and getupvalues then
            pcall(function()
                for _, f in ipairs(getgc(false)) do
                    if type(f) == "function" and islclosure(f) and fnSource(f):find("%.MovementTuning$") then
                        local ok, ups = pcall(getupvalues, f)
                        if ok then
                            for _, u in pairs(ups) do
                                if type(u) == "table" and type(rawget(u, "WALK_SPEED")) == "table" then speedTables[u.WALK_SPEED] = true end
                            end
                        end
                    end
                end
            end)
        end
        return next(speedTables) ~= nil
    end
    local BASE = { Run = 22, Walk = 10, Crouch = 8, Prone = 4 }
    local function applySpeed()
        if not speedResolved then return end
        local m = (RUNNING and Toggles.mv_speed.Value) and Opt.mv_speed_mult.Value or 1
        for ws in pairs(speedTables) do
            for k, v in pairs(BASE) do ws[k] = v * m end
        end
    end
    Toggles.mv_speed:OnChanged(function(v)
        if v and not resolveSpeed() then notify("Speed unavailable") end
        applySpeed()
    end)
    Opt.mv_speed_mult:OnChanged(applySpeed)
    onClean(function()
        for ws in pairs(speedTables) do for k, v in pairs(BASE) do ws[k] = v end end
    end)

    local AfB = MoveTab:AddRightGroupbox("AFK", "user")
    AfB:AddToggle("mv_antiafk", { Text = "Anti AFK", Default = true })
    local VU = game:GetService("VirtualUser")
    track(lp.Idled:Connect(function()
        if RUNNING and Toggles.mv_antiafk.Value then
            pcall(function() VU:CaptureController(); VU:ClickButton2(Vector2.new()) end)
        end
    end))

    local flyFall = false
    Toggles.mv_fly:OnChanged(function(v)
        if v then
            flyFall = not AC.dropFall
            AC.dropFall = true
        else
            task.delay(3, function()
                if not Toggles.mv_fly.Value and flyFall and not (Toggles.cw_nofall and Toggles.cw_nofall.Value) then
                    AC.dropFall = false
                end
            end)
        end
    end)
    track(RunService.Heartbeat:Connect(function()
        if not (RUNNING and Toggles.mv_fly.Value) then return end
        local char = lp.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local cam = Workspace.CurrentCamera
        if not (hrp and hum and cam) or hum.Health <= 0 or hum.SeatPart then return end
        local dir = hum.MoveDirection
        local cf = cam.CFrame
        local look = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
        local v = dir * Opt.mv_fly_speed.Value
        if dir.Magnitude > 0 and look.Magnitude > 0 then
            v = v + Vector3.new(0, cf.LookVector.Y * dir:Dot(look.Unit) * Opt.mv_fly_speed.Value, 0)
        end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then v = v + Vector3.new(0, Opt.mv_fly_speed.Value * 0.7, 0) end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then v = v - Vector3.new(0, Opt.mv_fly_speed.Value * 0.7, 0) end
        hrp.AssemblyLinearVelocity = v + Vector3.new(0, Workspace.Gravity * (1 / 60), 0)
    end))
    onClean(function() pcall(function() Toggles.mv_fly:SetValue(false) end) end)
end
section("Movement", _buildMovement)

local function _buildPerformance()
    local Lighting = game:GetService("Lighting")
    local PB = SettingsTab:AddRightGroupbox("Performance", "zap")
    PB:AddToggle("pf_shadows", { Text = "No Shadows", Default = false })
    PB:AddToggle("pf_grass", { Text = "No Grass", Default = false })
    PB:AddToggle("pf_weather", { Text = "No Weather", Default = false, Tooltip = "Removes rain, lightning and droplets" })
    PB:AddToggle("pf_corpses", { Text = "Clear Bodies", Default = false })
    PB:AddToggle("pf_casings", { Text = "No Shell Casings", Default = false })

    local shadowsSaved = nil
    Toggles.pf_shadows:OnChanged(function(v)
        if v then
            if shadowsSaved == nil then shadowsSaved = Lighting.GlobalShadows end
            Lighting.GlobalShadows = false
        elseif shadowsSaved ~= nil then
            Lighting.GlobalShadows = shadowsSaved
            shadowsSaved = nil
        end
    end)
    local terrain = Workspace:FindFirstChildOfClass("Terrain")
    local function getDeco()
        local ok, val = pcall(function() return terrain.Decoration end)
        if ok then return val end
        if gethiddenproperty then
            local ok2, v2 = pcall(gethiddenproperty, terrain, "Decoration")
            if ok2 then return v2 end
        end
        return nil
    end
    local function setDeco(val)
        if not pcall(function() terrain.Decoration = val end) and sethiddenproperty then
            pcall(sethiddenproperty, terrain, "Decoration", val)
        end
    end
    local decoSaved = nil
    Toggles.pf_grass:OnChanged(function(v)
        if not terrain then return end
        if v then
            local cur = getDeco()
            if cur == false then return end
            if decoSaved == nil then decoSaved = cur end
            setDeco(false)
        elseif decoSaved ~= nil then
            setDeco(decoSaved)
            decoSaved = nil
        end
    end)

    local function modOf(...)
        local cur = lp:FindFirstChild("PlayerScripts")
        for _, n in ipairs({ ... }) do cur = cur and cur:FindFirstChild(n) end
        if not cur then return nil end
        local ok, t = pcall(require, cur)
        return ok and type(t) == "table" and t or nil
    end
    local stubs = {}
    local function stub(t, keys)
        if not t then return end
        for _, k in ipairs(keys) do
            if type(t[k]) == "function" and not stubs[t] then stubs[t] = {} end
            if type(t[k]) == "function" and stubs[t][k] == nil then
                stubs[t][k] = t[k]
                t[k] = function() end
            end
        end
    end
    local function unstubAll()
        for t, keys in pairs(stubs) do for k, f in pairs(keys) do t[k] = f end end
        stubs = {}
    end
    Toggles.pf_weather:OnChanged(function(v)
        if v then
            local fx = modOf("WeatherClient", "WeatherFX")
            local lt = modOf("WeatherClient", "Lightning")
            local snd = modOf("WeatherClient", "ImpactSounds")
            local dr = modOf("WeatherClient", "ScreenDroplets")
            for _, m in ipairs({ fx, lt, snd, dr }) do
                if m and type(m.Stop) == "function" then gcall(m.Stop) end
            end
            stub(fx, { "SetProfile", "SetAmbience" })
            stub(lt, { "Start" })
            stub(snd, { "Start" })
            stub(dr, { "SetProfile", "SetExposure" })
            if not (fx or lt or dr) then notify("Weather controls not found") end
        else
            unstubAll()
        end
    end)

    local WE, origCasing
    Toggles.pf_casings:OnChanged(function(v)
        if v and not WE then
            pcall(function() WE = require(game:GetService("ReplicatedStorage").Client.WeaponEffects) end)
            origCasing = WE and WE.Casing
        end
        if not (WE and origCasing) then return end
        WE.Casing = v and function() end or origCasing
    end)

    task.spawn(function()
        while RUNNING do
            task.wait(3)
            if Toggles.pf_corpses.Value then
                local ig = Workspace:FindFirstChild("Ignore")
                if ig then
                    for _, c in ipairs(ig:GetChildren()) do
                        if c.Name:sub(-7) == "_Corpse" then pcall(function() c:Destroy() end) end
                    end
                    local dg = ig:FindFirstChild("DeadGear")
                    if dg then for _, c in ipairs(dg:GetChildren()) do pcall(function() c:Destroy() end) end end
                end
            end
        end
    end)

    onClean(function()
        unstubAll()
        if WE and origCasing then WE.Casing = origCasing end
        if shadowsSaved ~= nil then pcall(function() Lighting.GlobalShadows = shadowsSaved end) end
        if decoSaved ~= nil and terrain then setDeco(decoSaved) end
    end)
end
section("Performance", _buildPerformance)

section("Settings", function()
    local ACBox = SettingsTab:AddLeftGroupbox("Protection", "shield")
    local lblAC = ACBox:AddLabel("Guard: -", true)
    local lblHooks = ACBox:AddLabel("Hooks: -", true)
    local function mark(b) return b and "on" or "-" end
    local function refresh()
        lblAC:SetText(("Guard: %s · side %d/3 · icons %s"):format(
            AC.fireHooked and "on" or "OFF", AC.sideChannels or 0, AC.seedReady and "ok" or "-"))
        lblHooks:SetText(("Aim %s · Recoil %s · Rate %s · Cfg %s"):format(
            mark(SES.hooks.shot), mark(SES.hooks.recoil), mark(SES.hooks.cycle), mark(G.weapons ~= nil)))
    end
    refresh()
    task.spawn(function()
        while RUNNING do task.wait(2); pcall(refresh) end
    end)
    ACBox:AddToggle("cw_nofall", { Text = "No Fall Damage", Default = false,
        Callback = function(v) AC.dropFall = v end })

    local StB = SettingsTab:AddLeftGroupbox("Staff Detector", "eye")
    StB:AddToggle("st_on", { Text = "Staff Detector", Default = true, Tooltip = "Alerts when staff is in your server" })
    StB:AddDropdown("st_action", { Text = "When Staff Joins", Values = { "Notify", "Disable Cheats", "Server Hop", "Leave Game" }, Default = "Disable Cheats" })
    StB:AddToggle("st_restore", { Text = "Re-enable When They Leave", Default = true })
    local lblStaff = StB:AddLabel("Staff: none")
    local disabledByStaff = {}
    local function serverHop()
        local TS = game:GetService("TeleportService")
        local ok = pcall(function()
            local raw = game:HttpGet(("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100"):format(game.PlaceId))
            local data = HttpService:JSONDecode(raw)
            for _, s in ipairs(data.data or {}) do
                if s.id ~= game.JobId and (s.playing or 0) < (s.maxPlayers or 0) - 1 then
                    TS:TeleportToPlaceInstance(game.PlaceId, s.id, lp)
                    return
                end
            end
            error("no server")
        end)
        if not ok then pcall(function() TS:Teleport(game.PlaceId, lp) end) end
    end
    local PANIC = { "cw_silent", "cw_aimbot", "cw_trigger", "cw_rapid", "cw_fastreload",
        "mv_speed", "mv_fly", "ms_autorevive", "ms_autoheal", "ms_arty", "ms_autospot", "vh_on" }
    local function refreshStaff()
        local names = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if STAFF[p.UserId] then names[#names + 1] = p.Name end
        end
        lblStaff:SetText(#names == 0 and "Staff: none" or ("Staff: " .. table.concat(names, ", ")))
    end
    local function onStaff(p, why)
        if STAFF[p.UserId] then return end
        STAFF[p.UserId] = why
        refreshStaff()
        if not Toggles.st_on.Value then return end
        Library:Notify({ Title = "STAFF IN SERVER", Description = p.Name .. " (" .. why .. ")", Time = 15 })
        local act = Opt.st_action.Value
        if act == "Disable Cheats" then
            for _, k in ipairs(PANIC) do
                if Toggles[k] and Toggles[k].Value then
                    disabledByStaff[k] = true
                    pcall(function() Toggles[k]:SetValue(false) end)
                end
            end
        elseif act == "Server Hop" then
            notify("Hopping servers...")
            task.spawn(serverHop)
        elseif act == "Leave Game" then
            lp:Kick("Left: staff joined (" .. p.Name .. ")")
        end
    end
    local function checkPlayer(p)
        if p == lp then return end
        queueWeb(function()
            if not p.Parent then return end
            local ok, rank = pcall(p.GetRankInGroup, p, 32519006)
            if ok and type(rank) == "number" and rank >= 100 then
                local okR, role = pcall(p.GetRoleInGroup, p, 32519006)
                onStaff(p, okR and role or ("rank " .. rank))
            end
        end, true)
        if p:GetAttribute("Invisible") then onStaff(p, "invisible") end
        track(p:GetAttributeChangedSignal("Invisible"):Connect(function()
            if p:GetAttribute("Invisible") then onStaff(p, "invisible") end
        end))
    end
    for _, p in ipairs(Players:GetPlayers()) do checkPlayer(p) end
    track(Players.PlayerAdded:Connect(checkPlayer))
    track(Players.PlayerRemoving:Connect(function(p)
        if not STAFF[p.UserId] then return end
        STAFF[p.UserId] = nil
        pcall(refreshStaff)
        if next(STAFF) == nil and next(disabledByStaff) ~= nil and Toggles.st_restore.Value then
            for k in pairs(disabledByStaff) do
                if Toggles[k] then pcall(function() Toggles[k]:SetValue(true) end) end
            end
            disabledByStaff = {}
            notify("Staff left · cheats back on", 5)
        end
    end))

    local MenuBox = SettingsTab:AddRightGroupbox("Menu", "menu")
    MenuBox:AddLabel("Menu Toggle"):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = "Menu Toggle" })
    Library.ToggleKeybind = Opt.MenuKeybind
    MenuBox:AddButton({ Text = "Server Hop", Func = function() notify("Hopping servers...") task.spawn(serverHop) end })
    MenuBox:AddButton({ Text = "Unload", Func = function()
        pcall(function() if _G.__CW_VN_CLEAN then _G.__CW_VN_CLEAN() end end)
        pcall(function() Library:Unload() end)
    end })
end)


