crumb("DONE")

task.spawn(function()
    local frames, worst, last = 0, 0, os.clock()
    local hb = RunService.Heartbeat:Connect(function(dt)
        frames = frames + 1
        if dt > worst then worst = dt end
    end)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 120 do
        task.wait(2)
        local on = {}
        for k, t in pairs(Toggles) do
            if type(t) == "table" and t.Value == true and not k:find("^esp_") and k ~= "cw_wall" and k ~= "cw_sticky"
                and k ~= "cw_friends" and k ~= "cw_predict" and k ~= "cw_showfov" and k ~= "st_on" and k ~= "st_restore"
                and k ~= "mv_antiafk" and k ~= "esp_viscolor" then
                on[#on + 1] = k
            end
        end
        if Toggles.esp_on and Toggles.esp_on.Value then on[#on + 1] = "esp_on" end
        local now = os.clock()
        crumb(("alive · %d fps · worst frame %d ms · on: %s"):format(
            math.floor(frames / (now - last)), math.floor(worst * 1000), #on > 0 and table.concat(on, ",") or "-"))
        frames, worst, last = 0, 0, now
    end
    hb:Disconnect()
    crumb("watchdog finished")
end)

